_EMBEDDED = {
    "team": (_B0, True),
    "team.autopilot": (_B1, True),
    "team.detector": (_B2, True),
    "team.teacher": (_B3, True),
    "team.autopilot.agent": (_B4, False),
    "team.autopilot.freedir": (_B5, False),
    "team.detector.geom": (_B6, False),
    "team.detector.localize": (_B7, False),
    "team.detector.padnet": (_B8, False),
    "team.detector.pads": (_B9, False),
    "team.teacher.geometry": (_B10, False),
}


class _EmbeddedLoader(_iabc.InspectLoader):
    """Serve an embedded module's source to the normal import machinery.

    InspectLoader gives us exec_module and module_from_spec for free, so the
    modules get real `__spec__`/`__package__` values and relative imports inside
    the package resolve exactly as they do on disk.
    """

    def get_source(self, fullname):
        return _b64.b64decode(_EMBEDDED[fullname][0]).decode("utf-8")

    def is_package(self, fullname):
        return _EMBEDDED[fullname][1]

    def get_filename(self, fullname):
        # Point at this generated file so any Path(__file__) lookup inside the
        # package resolves against the unpacked bundle root.
        return __file__


class _EmbeddedFinder(_iabc.MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _EMBEDDED:
            return None
        loader = _EmbeddedLoader()
        spec = _iutil.spec_from_loader(
            fullname, loader, is_package=_EMBEDDED[fullname][1])
        if _EMBEDDED[fullname][1]:
            # A package with no real directory: empty search path, so submodules
            # are found only through this finder and never half-resolved from an
            # unrelated `team/` that happens to be on sys.path.
            spec.submodule_search_locations = []
        return spec


# Ahead of the path finders: a stale `team/` in the working directory must not
# shadow the version this zip was built and benchmarked from.
if not any(isinstance(_f, _EmbeddedFinder) for _f in _sys.meta_path):
    _sys.meta_path.insert(0, _EmbeddedFinder())

"""DroneFlightController — the V5.1 submission entry point for cf_swarm_autopilot.

The validator constructs this once, calls `reset()` per episode and `act(obs)` per
step, and hands `act` nothing but the observation: `depth` (N,128,128,1) and
`state` (N,190). No task metadata, no simulator, no ground truth. This family has
no RGB.

Behind it is exactly the code the benchmark scores:

    PadNetDetector       the depth segmenter, batched over the whole fleet
    SwarmAutopilotAgent  classify the map from the start pads, sweep the clue on
                         disjoint angular lanes, claim a corroborated pad, land

TWO checkpoints ship: a general model and a forest specialist, routed by the
agent's own forest test. Together they are 3.4 MB against a 50 MB uncompressed
cap (swarm/core/submission_policy.py), so carrying both costs nothing.

Budget: `act()` has RPC_STEP_TIMEOUT_SEC = 0.500 (2 s on the first call). The
detector runs every `detect_every` steps rather than every step and batches all N
drones into one forward pass. Timed by team/scripts/time_act.py — run it after
any change to the detector or the config, because a timeout scores nothing at
all, not a worse number.
"""

import os
import sys
from pathlib import Path

import numpy as np

_HERE = Path(__file__).resolve().parent
for _p in (_HERE, _HERE.parent, _HERE.parent.parent):
    if str(_p) not in sys.path:
        sys.path.insert(0, str(_p))

from team.autopilot.agent import AutopilotConfig, SwarmAutopilotAgent  # noqa: E402
from team.detector.pads import PadConfig                               # noqa: E402

